const lessons=[
{id:'cf196',subject:'Políticas Públicas de Saúde / SUS',topic:'Constituição Federal — arts. 196 a 200',title:'Saúde na Constituição: arts. 196 a 200',minutes:18,source:'constituicao',summary:'A Constituição define a saúde como direito de todos e dever do Estado e organiza a base do Sistema Único de Saúde.',points:['Art. 196: direito universal e dever estatal, garantido por políticas sociais e econômicas.','Art. 198: rede regionalizada e hierarquizada, com descentralização, integralidade e participação da comunidade.','Art. 199: assistência à saúde é livre à iniciativa privada, que pode participar de forma complementar do SUS.'],exam:'O IBDO costuma explorar troca de termos normativos. Atenção a universalidade, integralidade, descentralização e participação social.',flash:['Saúde é direito de todos e dever do Estado.','Art. 198: descentralização + integralidade + participação da comunidade.']},
{id:'l8080',subject:'Políticas Públicas de Saúde / SUS',topic:'Lei 8.080/1990 e alterações',title:'Lei 8.080: princípios, organização e competências',minutes:26,source:'lei8080',summary:'A Lei 8.080 detalha promoção, proteção e recuperação da saúde, bem como a organização e o funcionamento dos serviços do SUS.',points:['A direção do SUS é única em cada esfera de governo.','Integralidade articula ações preventivas e curativas, individuais e coletivas.','O campo de atuação do SUS inclui vigilância sanitária, epidemiológica e assistência terapêutica integral.'],exam:'Competências por esfera de governo e conceitos de vigilância são alvos clássicos de prova.',flash:['Direção do SUS: única em cada esfera.','Integralidade = ações preventivas + curativas articuladas.']},
{id:'l8142',subject:'Políticas Públicas de Saúde / SUS',topic:'Lei 8.142/1990 — participação social',title:'Lei 8.142: Conselhos, Conferências e transferências',minutes:16,source:'lei8142',summary:'A Lei 8.142 trata da participação da comunidade na gestão do SUS e das transferências intergovernamentais de recursos.',points:['Conselho de Saúde: permanente e deliberativo.','Conferência de Saúde: avalia a situação de saúde e propõe diretrizes.','Participação social integra a governança do SUS.'],exam:'A banca pode inverter “permanente” e “periódica” entre Conselho e Conferência.',flash:['Conselho = permanente e deliberativo.','Conferência = avalia situação e propõe diretrizes.']},
{id:'fv',subject:'Conhecimentos Específicos — Farmácia',topic:'Farmacoepidemiologia e farmacovigilância',title:'Farmacovigilância: conceitos e detecção de sinais',minutes:24,source:'anvisaFV',summary:'Farmacovigilância envolve detecção, avaliação, compreensão e prevenção de efeitos adversos ou outros problemas relacionados a medicamentos.',points:['Evento adverso não exige causalidade comprovada para ser notificado.','Erros de medicação, ineficácia terapêutica, abuso, intoxicação e interações podem integrar o escopo.','O monitoramento pós-comercialização complementa o conhecimento obtido antes do registro.'],exam:'Desconfie de alternativas que condicionem a notificação à certeza de causalidade.',flash:['Suspeita pode ser notificada sem causalidade comprovada.','Farmacovigilância vai além de reação adversa.']},
{id:'vigimed',subject:'Conhecimentos Específicos — Farmácia',topic:'Farmacoepidemiologia e farmacovigilância',title:'VigiMed: notificação e qualidade da informação',minutes:18,source:'vigimed',summary:'O VigiMed é o sistema da Anvisa para receber notificações de suspeitas de eventos adversos relacionados a medicamentos e vacinas.',points:['Profissionais e cidadãos podem realizar notificações.','Notificação espontânea auxilia na identificação de sinais de segurança.','Informações completas aumentam a utilidade da avaliação.'],exam:'Não confunda “suspeita de evento” com evento já confirmado por nexo causal.',flash:['VigiMed recebe suspeitas de eventos adversos.','Qualidade da informação melhora a avaliação do sinal.']},
{id:'rdc406',subject:'Conhecimentos Específicos — Farmácia',topic:'Farmacoepidemiologia e farmacovigilância',title:'RDC 406/2020 e IN 63/2020',minutes:22,source:'anvisa406',summary:'A RDC 406/2020 disciplina Boas Práticas de Farmacovigilância para detentores de registro e a IN 63/2020 trata do Relatório Periódico de Avaliação Benefício-Risco.',points:['O RPBR avalia periodicamente o perfil de segurança e a relação benefício-risco.','Detentores de registro possuem responsabilidades estruturadas de farmacovigilância.','A avaliação considera informações cumulativas e emergentes.'],exam:'Associe RDC 406 às boas práticas e IN 63 ao RPBR.',flash:['RDC 406/2020 = boas práticas de farmacovigilância.','IN 63/2020 = RPBR.']},
{id:'vigimed2026',subject:'Conhecimentos Específicos — Farmácia',topic:'Farmacoepidemiologia e farmacovigilância',title:'Atualização 2026: VigiMed Empresas',minutes:15,source:'vigimedEmp',summary:'A Anvisa publicou orientações atualizadas para o VigiMed Empresas, incluindo mudanças de padronização e transmissão de dados em farmacovigilância.',points:['Atualizações regulatórias devem ser estudadas pela fonte oficial vigente.','Mudanças de terminologia e padrões de transmissão podem ser cobradas em provas pós-edital.','Atenção especial a datas de vigência e transição.'],exam:'Este é um bloco de atualização. Priorize a redação oficial mais recente caso o tema seja cobrado.',flash:['Atualização regulatória: conferir sempre vigência e versão oficial.','Farmacovigilância exige padronização e rastreabilidade de dados.']},
{id:'pk',subject:'Conhecimentos Específicos — Farmácia',topic:'Farmacocinética — conceitos e parâmetros',title:'Farmacocinética: ADME, meia-vida e depuração',minutes:30,source:'anvisaFV',summary:'Farmacocinética descreve o que o organismo faz com o fármaco: absorção, distribuição, metabolismo e excreção.',points:['Biodisponibilidade representa a fração que alcança a circulação sistêmica de forma inalterada.','Depuração expressa a capacidade do organismo de eliminar o fármaco.','Meia-vida relaciona-se ao tempo necessário para reduzir a concentração plasmática pela metade em condições apropriadas.'],exam:'Questões costumam cruzar depuração, volume de distribuição, meia-vida, estado de equilíbrio e dose de ataque.',flash:['ADME = absorção, distribuição, metabolismo e excreção.','Depuração = capacidade de eliminação do fármaco.']},
{id:'pd',subject:'Conhecimentos Específicos — Farmácia',topic:'Farmacodinâmica e mecanismos de ação',title:'Farmacodinâmica: potência, eficácia e receptores',minutes:26,source:'anvisaFV',summary:'Farmacodinâmica estuda os efeitos do fármaco e seus mecanismos de ação, incluindo interação com receptores, potência e eficácia.',points:['Potência se relaciona à dose/concentração necessária para determinado efeito.','Eficácia corresponde ao efeito máximo alcançável.','Antagonistas reduzem ou impedem efeitos mediados pelo sistema receptor-alvo.'],exam:'Não confunda potência com eficácia: um fármaco mais potente não é necessariamente mais eficaz.',flash:['Potência ≠ eficácia.','Eficácia = efeito máximo alcançável.']}
];

const Q=(id,s,t,d,q,o,a,e,why,source='ibdo')=>({id,s,t,d,q,o,a,e,why,source,type:'Inédita — estilo IBDO'});
const baseQuestions=[
Q(1,'Políticas Públicas de Saúde / SUS','Constituição Federal — arts. 196 a 200','Fácil','De acordo com a Constituição Federal, a saúde é:', ['benefício restrito aos contribuintes da seguridade social','direito de todos e dever do Estado','competência exclusiva dos municípios','serviço público facultativo'],1,'O art. 196 estabelece a saúde como direito de todos e dever do Estado.','O erro mais comum é tratar a saúde pública como benefício contributivo. No SUS, o acesso é universal.','constituicao'),
Q(2,'Políticas Públicas de Saúde / SUS','Constituição Federal — arts. 196 a 200','Médio','Assinale a alternativa que apresenta somente diretrizes constitucionais do SUS previstas no art. 198:', ['centralização, atendimento seletivo e participação privada','descentralização, atendimento integral e participação da comunidade','hierarquização privada, universalidade contributiva e regionalização facultativa','descentralização, focalização e coparticipação financeira do usuário'],1,'O art. 198 traz descentralização, atendimento integral e participação da comunidade.','Memorize a tríade do art. 198. Alternativas erradas costumam inserir termos plausíveis, mas não previstos como diretrizes.','constituicao'),
Q(3,'Políticas Públicas de Saúde / SUS','Lei 8.080/1990 e alterações','Fácil','Segundo a Lei 8.080/1990, a direção do SUS é:', ['múltipla em todas as esferas','única em cada esfera de governo','exclusiva da União','exclusiva dos Conselhos de Saúde'],1,'A direção do SUS é única em cada esfera de governo.','O ponto-chave é “única em cada esfera”, não “única nacionalmente”.','lei8080'),
Q(4,'Políticas Públicas de Saúde / SUS','Lei 8.080/1990 e alterações','Médio','A integralidade da assistência no SUS corresponde, essencialmente, a:', ['priorização exclusiva de ações curativas','conjunto articulado e contínuo de ações e serviços preventivos e curativos','restrição das ações ao âmbito hospitalar','substituição da atenção básica por atenção especializada'],1,'Integralidade envolve articulação contínua de ações preventivas e curativas, individuais e coletivas.','Se você marcou “curativa”, confundiu integralidade com assistência centrada em doença.','lei8080'),
Q(5,'Políticas Públicas de Saúde / SUS','Lei 8.142/1990 — participação social','Fácil','O Conselho de Saúde é uma instância:', ['temporária e consultiva','permanente e deliberativa','eventual e executiva','privada e fiscalizatória'],1,'A Lei 8.142 define o Conselho de Saúde como permanente e deliberativo.','Conselho = permanente. Conferência = reunião periódica. Essa oposição resolve muitas questões.','lei8142'),
Q(6,'Políticas Públicas de Saúde / SUS','Lei 8.142/1990 — participação social','Médio','A Conferência de Saúde tem por finalidade principal:', ['executar diretamente ações de vigilância','avaliar a situação de saúde e propor diretrizes','substituir o Conselho de Saúde','autorizar individualmente transferências de recursos'],1,'A Conferência avalia a situação de saúde e propõe diretrizes para a política de saúde.','Não atribua à Conferência funções executivas ou permanentes do Conselho.','lei8142'),
Q(7,'Conhecimentos Específicos — Farmácia','Farmacoepidemiologia e farmacovigilância','Fácil','Em farmacovigilância, a notificação espontânea de suspeita de evento adverso:', ['exige nexo causal comprovado','pode ser realizada mesmo sem causalidade comprovada','somente pode ser feita pelo fabricante','é restrita a eventos fatais'],1,'A farmacovigilância trabalha com suspeitas; a causalidade pode ser avaliada posteriormente.','A palavra “suspeita” é central. Esperar certeza causal reduz a capacidade de detectar sinais.','anvisaFV'),
Q(8,'Conhecimentos Específicos — Farmácia','Farmacoepidemiologia e farmacovigilância','Médio','Qual situação também pode integrar o escopo da farmacovigilância?', ['somente reação adversa grave','erro de medicação e ineficácia terapêutica','apenas desvios administrativos sem relação com medicamento','somente intoxicação intencional'],1,'O escopo é amplo e pode incluir erros de medicação, ineficácia, abuso, intoxicação e interações.','Se você restringiu a farmacovigilância a reação adversa, revisite o conceito de “outros problemas relacionados a medicamentos”.','anvisaFV'),
Q(9,'Conhecimentos Específicos — Farmácia','Farmacoepidemiologia e farmacovigilância','Médio','Sobre o VigiMed, assinale a correta:', ['somente empresas podem notificar','cidadãos e profissionais de saúde podem notificar suspeitas de eventos adversos','é um sistema exclusivo para controle de estoque','substitui a investigação clínica individual'],1,'O VigiMed recebe notificações de diferentes perfis, incluindo cidadãos e profissionais.','Não confunda o perfil empresarial com o sistema como um todo.','vigimed'),
Q(10,'Conhecimentos Específicos — Farmácia','Farmacoepidemiologia e farmacovigilância','Médio','A associação normativa correta é:', ['RDC 406/2020 — RPBR; IN 63/2020 — boas práticas gerais','RDC 406/2020 — Boas Práticas de Farmacovigilância; IN 63/2020 — RPBR','RDC 406/2020 — controle de estoque; IN 63/2020 — farmacotécnica','RDC 406/2020 — prescrição; IN 63/2020 — dispensação'],1,'RDC 406/2020 trata das Boas Práticas de Farmacovigilância; IN 63/2020 disciplina o RPBR.','Faça a associação normativa como flashcard. É um alvo fácil para alternativas invertidas.','anvisa406'),
Q(11,'Conhecimentos Específicos — Farmácia','Farmacocinética — conceitos e parâmetros','Fácil','Farmacocinética estuda principalmente:', ['o que o fármaco faz ao organismo','o que o organismo faz com o fármaco','apenas o mecanismo receptor','somente toxicidade aguda'],1,'Farmacocinética descreve ADME: absorção, distribuição, metabolismo e excreção.','Use o mnemônico: cinética = caminho do fármaco pelo organismo.','anvisaFV'),
Q(12,'Conhecimentos Específicos — Farmácia','Farmacocinética — conceitos e parâmetros','Médio','A depuração de um fármaco representa:', ['o efeito máximo alcançado','a capacidade do organismo de eliminar o fármaco','a fração ligada ao receptor','a dose necessária para efeito máximo'],1,'Depuração é uma medida da eficiência de eliminação do fármaco.','Se confundiu com eficácia, você misturou farmacocinética com farmacodinâmica.','anvisaFV'),
Q(13,'Conhecimentos Específicos — Farmácia','Farmacocinética — conceitos e parâmetros','Médio','Biodisponibilidade é melhor definida como:', ['percentual de fármaco que se liga ao receptor','fração da dose que alcança a circulação sistêmica de forma inalterada','tempo até a concentração cair à metade','quantidade eliminada na urina em 24 horas'],1,'Biodisponibilidade descreve a fração que chega à circulação sistêmica de forma inalterada.','Não confunda biodisponibilidade com meia-vida ou excreção renal.','anvisaFV'),
Q(14,'Conhecimentos Específicos — Farmácia','Farmacodinâmica e mecanismos de ação','Fácil','Em farmacodinâmica, eficácia refere-se a:', ['velocidade de absorção','efeito máximo que um fármaco pode produzir','fração eliminada por via renal','tempo de meia-vida'],1,'Eficácia corresponde ao efeito máximo alcançável.','Potência fala da quantidade necessária; eficácia fala do teto de efeito.','anvisaFV'),
Q(15,'Conhecimentos Específicos — Farmácia','Farmacodinâmica e mecanismos de ação','Médio','Um fármaco A necessita de dose menor que B para produzir o mesmo efeito, mas ambos atingem o mesmo efeito máximo. A é:', ['mais eficaz e menos potente','mais potente, com eficácia semelhante','menos potente e mais eficaz','farmacocineticamente inativo'],1,'Se necessita menor dose para o mesmo efeito, A é mais potente; se o efeito máximo é igual, a eficácia é semelhante.','Esse é o contraste clássico entre potência e eficácia.','anvisaFV'),
Q(16,'Conhecimentos Específicos — Farmácia','Interações medicamentosas e reações adversas','Médio','Uma interação farmacocinética ocorre quando um medicamento altera:', ['a absorção, distribuição, metabolismo ou excreção de outro','apenas a afinidade de outro fármaco pelo receptor','somente o efeito placebo','exclusivamente a adesão do paciente'],0,'Interação farmacocinética modifica etapas de ADME de outro fármaco.','Se marcou receptor, isso descreve mais diretamente uma interação farmacodinâmica.','anvisaFV'),
Q(17,'Conhecimentos Específicos — Farmácia','Farmácia clínica e atenção farmacêutica','Médio','O uso racional de medicamentos pressupõe:', ['uso do medicamento mais novo disponível','medicamento apropriado à necessidade clínica, em dose e duração adequadas, com menor custo possível para paciente e comunidade','prescrição obrigatória de múltiplos medicamentos','substituição do diagnóstico por automedicação orientada'],1,'Uso racional considera necessidade clínica, dose, duração e custo adequado.','A resposta correta é multidimensional; “mais novo” ou “mais caro” não significa melhor uso.','anvisaFV'),
Q(18,'Conhecimentos Específicos — Farmácia','Seleção e padronização de medicamentos','Médio','A seleção de medicamentos em uma instituição deve priorizar:', ['preferências individuais sem critérios','evidências de eficácia, segurança, qualidade e custo-efetividade','somente o menor preço unitário','somente medicamentos recém-lançados'],1,'Seleção racional combina evidências clínicas, segurança, qualidade e critérios econômicos.','Menor preço isolado não representa necessariamente melhor custo-efetividade.','ibdo'),
Q(19,'Conhecimentos Específicos — Farmácia','Gestão em farmácia e gestão de estoque','Fácil','O estoque de segurança tem como principal função:', ['eliminar qualquer necessidade de inventário','proteger contra variações de consumo e atrasos de reposição','substituir o estoque regular','aumentar deliberadamente perdas por validade'],1,'Estoque de segurança reduz o risco de ruptura diante de variabilidade e atrasos.','Pense nele como “colchão” operacional, não como excesso permanente.','ibdo'),
Q(20,'Conhecimentos Específicos — Farmácia','Gestão em farmácia e gestão de estoque','Médio','Em gestão de estoque, o método PEPS/FEFO deve priorizar:', ['itens mais caros independentemente da validade','itens com vencimento mais próximo','itens recebidos por último','itens com menor consumo'],1,'No contexto de validade, FEFO prioriza o que expira primeiro, reduzindo perdas.','A lógica é reduzir vencimento: primeiro a expirar, primeiro a sair.','ibdo'),
Q(21,'Conhecimentos Específicos — Farmácia','Sistemas de distribuição de medicamentos','Médio','Uma vantagem do sistema de dose unitária em ambiente hospitalar é:', ['reduzir rastreabilidade','aumentar manipulações desnecessárias na unidade','favorecer identificação, rastreabilidade e controle da dispensação por paciente','dispensar conferência farmacêutica'],2,'A dose unitária favorece rastreabilidade, identificação e controle individualizado.','Se você marcou alternativa que reduz controle, revise o objetivo de segurança do sistema.','ibdo'),
Q(22,'Conhecimentos Específicos — Farmácia','Farmacotécnica de produtos estéreis','Médio','A técnica asséptica tem como objetivo principal:', ['aumentar a concentração do princípio ativo','minimizar contaminação durante preparo e manipulação','substituir validação de processo','eliminar necessidade de controle ambiental'],1,'Técnica asséptica reduz o risco de contaminação durante manipulações estéreis.','Técnica asséptica é parte do sistema de garantia da esterilidade, não substitui controle ambiental ou validação.','ibdo'),
Q(23,'Conhecimentos Específicos — Farmácia','Farmacotécnica de produtos não estéreis','Médio','A estabilidade de uma preparação extemporânea depende, entre outros fatores, de:', ['somente da cor da embalagem','composição, pH, temperatura, luz e condições de armazenamento','apenas do nome comercial do insumo','exclusivamente do volume final'],1,'Estabilidade é multifatorial e depende de características da formulação e armazenamento.','Se uma alternativa reduz estabilidade a um único fator, desconfie.','ibdo'),
Q(24,'Conhecimentos Específicos — Farmácia','Biossegurança','Fácil','Em biossegurança, o uso de EPI:', ['substitui todas as medidas coletivas','é uma barreira complementar dentro de uma estratégia de prevenção','é opcional em atividades de risco','serve apenas para proteger o produto, nunca o trabalhador'],1,'EPI integra um conjunto de medidas de prevenção e não substitui controles coletivos e organizacionais.','Pense na hierarquia de controles: EPI é importante, mas não é a única barreira.','ibdo'),
Q(25,'Português','Compreensão e interpretação de texto','Médio','Em uma questão de interpretação, uma inferência válida deve:', ['contradizer o texto para ampliar o sentido','ser sustentada por elementos do texto, ainda que não esteja explicitada literalmente','depender apenas da opinião pessoal do leitor','ignorar conectivos e relações semânticas'],1,'Inferência é uma conclusão apoiada em pistas textuais, não mero palpite.','Se você escolheu opinião pessoal, confundiu interpretação com leitura subjetiva sem evidência.','ibdo'),
Q(26,'Português','Coesão e coerência textuais','Médio','O emprego de conectivos contribui para a coesão porque:', ['elimina a necessidade de relações lógicas','estabelece relações entre segmentos do texto','impede a progressão temática','substitui integralmente a pontuação'],1,'Conectivos sinalizam relações de causa, oposição, conclusão, condição, adição etc.','Identifique o valor semântico do conectivo antes de escolher a alternativa.','ibdo'),
Q(27,'Português','Crase','Fácil','Assinale a situação em que, em regra, pode ocorrer crase:', ['antes de verbo','antes de palavra masculina','na fusão da preposição a com artigo feminino a','antes de pronome pessoal'],2,'Crase resulta, classicamente, da fusão de dois sons idênticos, como preposição a + artigo a.','Antes de verbo e de palavra masculina, em regra, não há artigo feminino que permita essa fusão.','ibdo'),
Q(28,'Português','Concordância nominal e verbal','Médio','A concordância verbal deve considerar prioritariamente:', ['a proximidade gráfica de qualquer substantivo','a relação entre o verbo e o núcleo do sujeito, observadas as regras específicas','somente a palavra imediatamente anterior ao verbo','a preferência estilística do autor, sem regras'],1,'A concordância se estabelece com o sujeito e seu núcleo, respeitadas construções especiais.','Evite a “concordância por proximidade” automática. Primeiro identifique o sujeito.','ibdo'),
Q(29,'Português','Regência nominal e verbal','Médio','O estudo de regência verbal busca identificar:', ['a posição do acento tônico','a relação entre o verbo e seus complementos, inclusive preposições exigidas','a formação dos tempos verbais','apenas a concordância do verbo com o sujeito'],1,'Regência trata da relação sintática e das preposições exigidas por verbos e nomes.','Regência ≠ concordância. Regência pergunta “quem exige qual complemento/preposição?”.','ibdo'),
Q(30,'Português','Pontuação','Médio','A vírgula não deve, em regra, separar:', ['termos de uma enumeração','orações coordenadas em certos contextos','sujeito e verbo','adjuntos adverbiais deslocados extensos'],2,'Separar sujeito e verbo por vírgula é erro clássico, salvo estruturas incidentais específicas.','Localize o núcleo do sujeito e o verbo antes de inserir vírgula.','ibdo'),
Q(31,'Conhecimentos Específicos — Farmácia','Farmacoepidemiologia e farmacovigilância','Difícil','Um relato descreve um evento clinicamente relevante ocorrido após o uso de um medicamento, sem evidência suficiente para estabelecer nexo causal. Para fins de farmacovigilância, a conduta conceitualmente mais adequada é:', ['descartar o relato por ausência de causalidade confirmada','considerar a possibilidade de notificação como suspeita e permitir avaliação posterior','classificar automaticamente como reação adversa confirmada','aguardar necessariamente novo evento no mesmo paciente'],1,'A notificação de suspeita não exige causalidade confirmada; a avaliação do nexo é etapa posterior.','A banca pode explorar a diferença entre temporalidade, suspeita e causalidade.','anvisaFV'),
Q(32,'Conhecimentos Específicos — Farmácia','Farmacocinética — conceitos e parâmetros','Difícil','Mantidos os demais parâmetros, uma redução importante da depuração tende a:', ['reduzir a exposição sistêmica','aumentar a exposição e potencialmente prolongar a meia-vida','eliminar a necessidade de ajuste posológico','reduzir obrigatoriamente a biodisponibilidade'],1,'Menor depuração significa menor capacidade de eliminação, podendo elevar exposição e prolongar meia-vida.','Relacione depuração à eliminação. Biodisponibilidade não é necessariamente afetada.','anvisaFV'),
Q(33,'Conhecimentos Específicos — Farmácia','Farmacodinâmica e mecanismos de ação','Difícil','Dois agonistas atingem o mesmo efeito máximo, mas um deles necessita de concentração muito menor. É correto afirmar que:', ['o que necessita menor concentração é mais potente','o que necessita menor concentração é necessariamente mais eficaz','ambos têm potências idênticas','a diferença observada é exclusivamente farmacocinética'],0,'Mesma eficácia máxima, porém concentração menor para o mesmo efeito, indica maior potência.','Repita: potência = quanto precisa; eficácia = quanto consegue fazer no máximo.','anvisaFV'),
Q(34,'Conhecimentos Específicos — Farmácia','Gestão em farmácia e gestão de estoque','Difícil','Em um item com consumo variável e tempo de reposição sujeito a atrasos, a ausência de estoque de segurança aumenta principalmente o risco de:', ['sobrestoque inevitável','ruptura de estoque','aumento automático da validade','redução da demanda clínica'],1,'O estoque de segurança existe para reduzir risco de ruptura diante de incerteza de consumo e reposição.','Não confunda estoque de segurança com estoque máximo.','ibdo'),
Q(35,'Políticas Públicas de Saúde / SUS','Lei 8.080/1990 e alterações','Difícil','Uma alternativa afirma que a integralidade no SUS se limita à oferta de todos os procedimentos disponíveis em um único estabelecimento. Essa afirmação é:', ['correta, pois integralidade é sinônimo de concentração de serviços','incorreta, porque integralidade envolve articulação de ações e serviços em diferentes níveis e necessidades','correta apenas na atenção hospitalar','correta sempre que houver financiamento federal'],1,'Integralidade não exige que tudo esteja no mesmo estabelecimento; pressupõe articulação da rede e cuidado conforme necessidades.','A palavra “integral” não significa “tudo no mesmo lugar”.','lei8080'),
Q(36,'Português','Compreensão e interpretação de texto','Difícil','Quando uma alternativa apresenta uma conclusão compatível com o texto, mas mais ampla do que as informações permitem, ela deve ser considerada:', ['correta por ser plausível','incorreta por extrapolação','correta se tiver linguagem formal','incorreta apenas se houver erro gramatical'],1,'Em interpretação, plausibilidade externa não basta: a conclusão precisa respeitar os limites informacionais do texto.','IBDO e outras bancas usam extrapolações plausíveis para distrair o candidato.','ibdo')
];


